const (
	automationGraphNodeWidth  = 170.0
	automationGraphNodeHeight = 104.0
	automationGraphPadding    = 60.0
)

func automationDraftCandidateJSON(candidate models.AutomationDraftCandidate) string {
	value, _ := json.Marshal(candidate)
	return string(value)
}
func automationDraftHasConfig(node models.AutomationDraftNode, key string) bool {
	_, ok := node.Config[key]
	return ok
}
func automationDraftStringConfig(node models.AutomationDraftNode, key string) string {
	value, _ := node.Config[key].(string)
	return value
}
func automationDraftIntConfig(node models.AutomationDraftNode, key string) int {
	switch value := node.Config[key].(type) {
	case int:
		return value
	case float64:
		return int(value)
	case json.Number:
		parsed, _ := value.Int64()
		return int(parsed)
	}
	return 0
}
func automationDraftBoolConfig(node models.AutomationDraftNode, key string) bool {
	value, _ := node.Config[key].(bool)
	return value
}
func automationDraftHasNode(nodes []models.AutomationDraftNode, key string) bool {
	for _, node := range nodes {
		if node.Key == key {
			return true
		}
	}
	return false
}
func automationDraftHasEdge(edges []models.AutomationDraftEdge, key string) bool {
	for _, edge := range edges {
		if edge.Key == key {
			return true
		}
	}
	return false
}
func automationDraftNodeName(nodes []models.AutomationDraftNode, key string) string {
	for _, node := range nodes {
		if node.Key == key {
			return node.Name
		}
	}
	return key
}
func automationDraftDefaultX(nodes []models.AutomationDraftNode, key string) float64 {
	for _, node := range nodes {
		if node.Key == key && node.Position != nil {
			return node.Position.X
		}
	}
	return 0
}
func automationDraftDefaultY(nodes []models.AutomationDraftNode, key string) float64 {
	for _, node := range nodes {
		if node.Key == key && node.Position != nil {
			return node.Position.Y
		}
	}
	return 0
}
func automationDraftGraphViewBox(nodes []models.AutomationDraftNode) string {
	var first *models.AutomationDraftPoint
	for _, node := range nodes {
		if node.Position != nil {
			first = node.Position
			break
		}
	}
	if first == nil {
		return "-60 -60 900 540"
	}
	minX, minY, maxX, maxY := first.X, first.Y, first.X+automationGraphNodeWidth, first.Y+automationGraphNodeHeight
	for _, node := range nodes {
		if node.Position == nil {
			continue
		}
		if node.Position.X < minX {
			minX = node.Position.X
		}
		if node.Position.Y < minY {
			minY = node.Position.Y
		}
		if node.Position.X+automationGraphNodeWidth > maxX {
			maxX = node.Position.X + automationGraphNodeWidth
		}
		if node.Position.Y+automationGraphNodeHeight > maxY {
			maxY = node.Position.Y + automationGraphNodeHeight
		}
	}
	return fmt.Sprintf("%.0f %.0f %.0f %.0f", minX-automationGraphPadding, minY-automationGraphPadding, maxX-minX+2*automationGraphPadding, maxY-minY+2*automationGraphPadding)
}
func automationDraftEdgeNodes(nodes []models.AutomationDraftNode, edge models.AutomationDraftEdge) (models.AutomationDraftNode, models.AutomationDraftNode, bool) {
	var source, target models.AutomationDraftNode
	var sourceOK, targetOK bool
	for _, node := range nodes {
		if node.Key == edge.From {
			source, sourceOK = node, node.Position != nil
		}
		if node.Key == edge.To {
			target, targetOK = node, node.Position != nil
		}
	}
	return source, target, sourceOK && targetOK
}
func automationNodeTypeLabel(nodeType models.AutomationNodeType) string {
	return strings.Title(strings.ReplaceAll(string(nodeType), "_", " "))
}

func automationMetricsJSON(metrics models.AutomationMetrics) string {
	value, _ := json.Marshal(metrics)
	return string(value)
}
func automationReplayJSON(frames []models.AutomationReplayFrame) string {
	value, _ := json.Marshal(frames)
	return string(value)
}
func automationHealthBadgeClass(state models.AutomationHealthState) string {
	switch state {
	case models.AutomationHealthHealthy:
		return "badge badge-success badge-outline"
	case models.AutomationHealthDegraded:
		return "badge badge-warning badge-outline"
	case models.AutomationHealthUnhealthy:
		return "badge badge-error badge-outline"
	}
	return "badge badge-ghost"
}
func automationInvocationHistoryTime(invocation models.AutomationInvocation) time.Time {
	if invocation.ScheduledFor != nil {
		return *invocation.ScheduledFor
	}
	if invocation.StartedAt != nil {
		return *invocation.StartedAt
	}
	return invocation.CreatedAt
}
func automationInvocationLabel(invocation models.AutomationInvocation) string {
	if invocation.ScheduledFor != nil {
		return "Scheduled occurrence"
	}
	return "Invocation " + automationShortID(invocation.ID)
}
func automationWorkItemLabel(item models.AutomationWorkItem) string {
	if strings.TrimSpace(item.Title) != "" {
		return item.Title
	}
	return item.Kind + " " + automationShortID(item.ID)
}
func automationShortID(value string) string {
	if len(value) <= 8 {
		return value
	}
	return value[:8]
}
func automationNodeName(nodes []models.AutomationNode, nodeID string) string {
	for _, node := range nodes {
		if node.ID == nodeID {
			return node.Name
		}
	}
	return "Unknown node"
}
func automationInvocationNodeClass(history models.AutomationInvocationHistory, nodeID string) string {
	for _, touchedNodeID := range history.TouchedNodeIDs {
		if touchedNodeID == nodeID {
			return "automation-graph-node automation-graph-node--running"
		}
	}
	return "automation-graph-node automation-graph-node--idle"
}

func automationCardSearchText(card models.AutomationCard) string {
	return strings.Join([]string{card.Automation.Name, card.Automation.Description, card.Version.AdapterKey, string(card.Automation.LifecycleState), string(card.Automation.HealthState)}, " ")
}
func automationTime(value *time.Time, empty string) string {
	if value == nil {
		return empty
	}
	return value.Local().Format("Jan 2, 3:04 PM")
}
func automationGraphViewBox(nodes []models.AutomationNode) string {
	if len(nodes) == 0 {
		return "-60 -60 900 540"
	}
	minX, minY := automationGraphLayoutX(nodes[0].PositionX), automationGraphLayoutY(nodes[0].PositionY)
	maxX, maxY := minX+automationGraphNodeWidth, minY+automationGraphNodeHeight
	for _, node := range nodes {
		x, y := automationGraphLayoutX(node.PositionX), automationGraphLayoutY(node.PositionY)
		if x < minX {
			minX = x
		}
		if y < minY {
			minY = y
		}
		if x+automationGraphNodeWidth > maxX {
			maxX = x + automationGraphNodeWidth
		}
		if y+automationGraphNodeHeight > maxY {
			maxY = y + automationGraphNodeHeight
		}
	}
	return fmt.Sprintf("%.0f %.0f %.0f %.0f", minX-automationGraphPadding, minY-automationGraphPadding, maxX-minX+2*automationGraphPadding, maxY-minY+2*automationGraphPadding)
}
func automationEdgeNodes(nodes []models.AutomationNode, edge models.AutomationEdge) (models.AutomationNode, models.AutomationNode, bool) {
	var source, target models.AutomationNode
	var foundSource, foundTarget bool
	for _, n := range nodes {
		if n.ID == edge.SourceNodeID {
			source, foundSource = n, true
		}
		if n.ID == edge.TargetNodeID {
			target, foundTarget = n, true
		}
	}
	return source, target, foundSource && foundTarget
}
func automationNodeLabel(value string, limit int) string {
	r := []rune(value)
	if len(r) <= limit {
		return value
	}
	return string(r[:limit-1]) + "…"
}
func resourcesForAutomationNode(resources []models.AutomationResourceSummary, nodeID string) []models.AutomationResourceSummary {
	var out []models.AutomationResourceSummary
	for _, resource := range resources {
		if resource.NodeID == nodeID {
			out = append(out, resource)
		}
	}
	return out
}

